def decide(trace):
    if not trace:
        return (None, None, 'the qualifying synchronized SDA transition never occurred')

    triggers = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['inputs'].get('sda_i')
        row = trace[i]
        cur = row['inputs'].get('sda_i')
        scl = row['inputs'].get('scl_i')
        if prev == 1 and cur == 0 and scl == 1:
            triggers.append(i)

    if not triggers:
        return (None, None, 'the qualifying synchronized SDA falling transition with SCL high never occurred')

    for i in triggers:
        for j in range(i + 1, len(trace)):
            before = trace[j - 1]['outputs'].get('busy')
            after = trace[j]['outputs'].get('busy')
            if before == 0 and after == 1:
                return (True, trace[j]['edge'], 'busy rose after the qualifying SDA transition, indicating the filter sampling effect became visible')

    return (False, trace[triggers[0]]['edge'], 'busy did not rise after the qualifying SDA transition; no observable filter-sampling effect was produced')

def decide(trace):
    # The route applies only during an active command sequence.
    segments = []
    start = None
    for i, row in enumerate(trace):
        active = row['outputs'].get('busy') == 1
        prev_active = i > 0 and trace[i - 1]['outputs'].get('busy') == 1
        if active and not prev_active:
            if start is not None:
                segments.append((start, i))
            start = i
    if start is not None:
        segments.append((start, len(trace)))

    event_rows = []
    ordinary_completion = False
    incomplete_event = None

    for begin, end in segments:
        events = []
        for i in range(begin, end):
            if i == 0:
                continue
            prev = trace[i - 1]['inputs'].get('scl_i')
            cur = trace[i]['inputs'].get('scl_i')
            released = trace[i]['outputs'].get('scl_oen') == 1
            if prev is not None and cur is not None and prev > cur and released:
                events.append(i)
                event_rows.append(i)

        ack_rows = [
            i for i in range(begin, end)
            if trace[i]['outputs'].get('cmd_ack') == 1
        ]

        if not events and ack_rows:
            ordinary_completion = True

        for event in events:
            if trace[event]['outputs'].get('cmd_ack') == 1:
                return (False, trace[event]['edge'],
                        'cmd_ack was asserted on the falling scl_i event; the completion pulse was not postponed')
            later_ack = [i for i in ack_rows if i > event]
            if later_ack:
                continue
            if incomplete_event is None:
                incomplete_event = event

    if not event_rows:
        return (None, None, 'no falling scl_i transition while busy and scl_oen was high')
    if not ordinary_completion:
        return (None, None,
                'the resynchronization case occurred, but no event-free command completion was observed for comparison')
    if incomplete_event is not None:
        return (None, trace[incomplete_event]['edge'],
                'a falling scl_i event while scl_oen was high was observed, but the trace ended before a postponed cmd_ack completion pulse')

    return (True, trace[event_rows[-1]]['edge'],
            'falling scl_i events while busy and scl_oen high kept cmd_ack low until a later completion; an event-free completion pulse was also observed')

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def _level(port, value):
    return lambda row: row['outputs'].get(port) == value


def decide(trace):
    checks = []
    cases = [
        ('scl_oen', 0, 'scl_o', 0),
        ('sda_oen', 0, 'sda_o', 0),
    ]

    for enable, enable_value, line, line_value in cases:
        windows = after(
            trace,
            _level(enable, enable_value),
            until=WHILE_ACTIVE,
        )
        checks.extend(
            throughout(
                window,
                _level(line, line_value),
            )
            for window in windows
        )

    result = worst(checks)
    if result[0] is None:
        return (None, None, 'no low output-enable state occurred; the pulled-low cases were not exercised')
    return result

def decide(trace):
    from specflow.refmodel.temporal import after, edges, sequence, worst

    def any_condition(alternatives):
        def predicate(row):
            return any(
                all(row['outputs'].get(port, row['inputs'].get(port)) == value
                    for port, value in condition.items())
                for condition in alternatives
            )
        return predicate

    # No cmd encoding table is declared.  Use the STOP-shaped output signature
    # rather than inventing a numeric cmd encoding.
    sda_driven = edges(trace, 'sda_oen', 'fall')
    scl_released = edges(trace, 'scl_oen', 'rise')
    sda_released = edges(trace, 'sda_oen', 'rise')

    opens = lambda row: (
        row['edge'] in sda_driven
        and row['outputs'].get('sda_oen') == 0
        and row['inputs'].get('ena') == 1
    )
    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        opens,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=aborts,
    )

    def released_scl(row):
        return (
            row['edge'] in scl_released
            and row['outputs'].get('scl_oen') == 1
        )

    def released_sda_while_scl_high(row):
        return (
            row['edge'] in sda_released
            and row['outputs'].get('sda_oen') == 1
            and row['outputs'].get('scl_oen') == 1
        )

    def acknowledged(row):
        return row['outputs'].get('cmd_ack') == 1

    return worst([
        sequence(
            window,
            released_scl,
            released_sda_while_scl_high,
            acknowledged,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # No command encoding is stated.  Use the declared output signature of
    # the bit-level sequence instead of inventing a numeric READ command value.
    running = holds({'busy': 1})
    aborted = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        running,
        until=TO_END,
        aborts=aborted,
    )

    follows = False
    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('cmd_ack') == 1,
            after_activation=follows,
            strong=True,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, sequence, throughout, worst

    scl_oen_rises = edges(trace, "scl_oen", "rise")

    def stretched_release(row):
        return (row["edge"] in scl_oen_rises
                and row["inputs"].get("scl_i") == 0)

    windows = after(trace, stretched_release, until=TO_END)
    follows = False

    def ack_not_during_stretch(row):
        return (row["inputs"].get("scl_i") != 0
                or row["outputs"].get("cmd_ack") == 0)

    def scl_released(row):
        return row["inputs"].get("scl_i") == 1

    def ack_pulses(row):
        return row["outputs"].get("cmd_ack") == 1

    verdicts = []
    for w in windows:
        verdicts.append(
            throughout(w, ack_not_during_stretch,
                       after_activation=follows)
        )
        verdicts.append(
            sequence(w, scl_released, ack_pulses,
                     strong=False, after_activation=follows)
        )

    return worst(verdicts)

def decide(trace):
    checks = []
    for row in trace:
        inputs = row['inputs']
        outputs = row['outputs']

        # Arbitration-checking signature: busy while SDA is released.
        # sda_i is used only to qualify the condition being checked.
        in_check = (
            inputs.get('nReset') != 0 and
            inputs.get('rst') != 1 and
            outputs.get('busy') == 1 and
            outputs.get('sda_oen') == 1 and
            inputs.get('sda_i') == 0
        )
        if in_check:
            checks.append(row)

    if not checks:
        return (None, None,
                'arbitration-checking condition with released SDA and observed low sda_i never occurred')

    for row in checks:
        if row['outputs'].get('al') != 1:
            return (False, row['edge'],
                    'during arbitration checking, sda_i was low while SDA was released but al was not asserted high')

    return (True, checks[-1]['edge'],
            f'al was asserted high for all {len(checks)} applicable arbitration-checking state(s)')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def applies(row):
        return row['outputs'].get('al') == 1

    def released(row):
        return (row['outputs'].get('scl_oen') == 1 and
                row['outputs'].get('sda_oen') == 1)

    windows = after(trace, applies, until=TO_END)
    return worst([
        eventually(w, released, strong=True, after_activation=False)
        for w in windows
    ])

def decide(trace):
    # `busy` is the declared output signature for an active command sequence.
    active = [r for r in trace if r['outputs'].get('busy') == 1]
    if not active:
        return (None, None, 'no active command sequence was observed (busy never asserted)')

    transitions = []
    previous = None
    elapsed = 0
    configured = None

    for row in trace:
        busy = row['outputs'].get('busy') == 1
        scl_oen = row['outputs'].get('scl_oen')
        clk_cnt = row['inputs'].get('clk_cnt')
        held = row.get('held', 1)

        if not busy:
            previous = None
            elapsed = 0
            configured = None
            continue

        if previous is None:
            previous = scl_oen
            elapsed = held
            configured = clk_cnt
            continue

        if scl_oen != previous:
            transitions.append((row, elapsed, configured))
            previous = scl_oen
            elapsed = held
            configured = clk_cnt
        else:
            elapsed += held

    if len(transitions) < 2:
        return (None, None, 'active sequence observed, but no successive scl_oen phase boundaries were available')

    for row, interval, prescale in transitions:
        if isinstance(prescale, int) and interval < prescale:
            return (False, row['edge'],
                    f'scl_oen phase transition occurred after {interval} edges, before the configured clk_cnt interval of {prescale}')

    return (True, transitions[-1][0]['edge'],
            f'{len(transitions)} scl_oen phase transitions were separated by at least their configured clk_cnt intervals')

def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['outputs']
        row = trace[i]['outputs']
        if prev.get('busy') == 1 and row.get('busy') == 0:
            completions.append(i)

    if not completions:
        return (None, None, 'no command completion signature was observed: busy did not transition from asserted to deasserted')

    for i in completions:
        row = trace[i]
        edge = row['edge']
        if row['outputs'].get('cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not asserted when the command completion signature occurred')

        if i > 0 and trace[i - 1]['outputs'].get('cmd_ack') == 1:
            return (False, edge, 'cmd_ack was already asserted before command completion')

        total = 0
        j = i
        while j < len(trace) and trace[j]['outputs'].get('cmd_ack') == 1:
            total += trace[j]['held']
            j += 1

        if total != 1:
            return (False, edge, f'cmd_ack was asserted for {total} edges; the requirement states exactly one clk cycle')

        if j == len(trace):
            return (None, edge, 'cmd_ack was high for one observed edge, but the trace ended before deassertion could be observed')

    return (True, None, 'cmd_ack was asserted for exactly one clk cycle at every observed command completion')

def decide(trace):
    start_events = []
    ordinary_cases = []

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        # The activation is not applicable during reset.
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue

        busy_now = outputs.get('busy')
        if busy_now != 0:
            continue

        previous = trace[i - 1] if i > 0 else None
        previous_inputs = previous.get('inputs', {}) if previous else {}
        sda_fell = (
            previous is not None and
            previous_inputs.get('sda_i') == 1 and
            inputs.get('sda_i') == 0
        )

        is_start = sda_fell and inputs.get('scl_i') == 1
        if is_start:
            # The route says busy is low before the START boundary and rises
            # at that boundary.  A current low value is therefore a failure.
            start_events.append(row)
        else:
            # Evidence of the ordinary route case: no START is present while
            # busy remains low.  This is evidence only, not a second
            # obligation asserted under this requirement.
            ordinary_cases.append(row)

    if not start_events:
        return (None, None, 'no applicable high-SCL SDA falling transition while busy was low')

    failed = []
    for row in start_events:
        # Re-evaluate the boundary output without using it as the trigger.
        i = trace.index(row)
        current_busy = trace[i].get('outputs', {}).get('busy')
        if current_busy != 1:
            failed.append(row)

    if failed:
        row = failed[0]
        return (False, row['edge'], 'busy did not rise at the START boundary')

    if not ordinary_cases:
        return (None, start_events[0]['edge'], 'START behavior was seen, but no ordinary non-START route case was observed')

    return (True, start_events[0]['edge'], 'busy rose at the high-SCL SDA falling START boundary; ordinary non-START behavior was also observed')

def decide(trace):
    rows = [r for r in trace if 'scl_oen' in r.get('outputs', {})]
    if not rows:
        return (None, None, 'scl_oen is absent from the trace')
    return (None, rows[0].get('edge'), 'The obligation names no falsifiable scl_oen effect; no licensed assertion can be made.')

def decide(trace):
    events = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        inputs = row['inputs']
        outputs = row['outputs']
        prev_inputs = prev['inputs']
        stop_event = prev_inputs.get('sda_i') == 0 and inputs.get('sda_i') == 1
        active_non_stop_signature = (
            inputs.get('ena') == 1 and
            inputs.get('nReset') == 1 and
            inputs.get('rst') == 0 and
            outputs.get('busy') == 1 and
            inputs.get('scl_i') == 1
        )
        if stop_event and active_non_stop_signature:
            events.append(row)

    if not events:
        return (None, None, 'no STOP-shaped event occurred while the declared active non-STOP sequence signature was present')

    for row in events:
        if row['outputs'].get('al') != 1:
            return (False, row['edge'], 'al was not asserted high when the STOP condition occurred during the active non-STOP sequence')

    return (True, events[-1]['edge'], f'al was asserted for all {len(events)} qualified STOP event(s)')

def decide(trace):
    qualified = [
        r for r in trace
        if r['inputs'].get('rst') == 1 and r['inputs'].get('nReset') == 1
    ]
    if not qualified:
        return (None, None, 'synchronous reset activation rst=1 with nReset=1 never occurred')

    expected = {
        'busy': 0,
        'al': 0,
        'cmd_ack': 0,
        'scl_oen': 1,
        'sda_oen': 1,
    }
    for row in qualified:
        bad = [
            '%s=%r (expected %r)' % (port, row['outputs'].get(port), value)
            for port, value in expected.items()
            if row['outputs'].get(port) != value
        ]
        if bad:
            return (False, row['edge'],
                    'after a rising edge with rst high and nReset high, reset outputs were wrong: '
                    + ', '.join(bad))

    return (True, qualified[-1]['edge'],
            'all qualified synchronous-reset states had busy=0, al=0, cmd_ack=0, '
            'scl_oen=1, and sda_oen=1')

def decide(trace):
    def out(row, port):
        return row['outputs'].get(port)

    def aborted(row):
        return (row['outputs'].get('al') == 1 or
                row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    # With no declared cmd encoding, use the START-shaped output signature.
    candidates = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        cur = trace[i]
        if (out(prev, 'sda_oen') != 0 and
                out(cur, 'sda_oen') == 0 and
                out(cur, 'scl_oen') == 1 and
                not aborted(cur)):
            candidates.append(i)

    if not candidates:
        return (None, None,
                'START command encoding is unspecified and no START-shaped SDA pull-low transition occurred')

    i = candidates[0]
    if aborted(trace[i]):
        return (None, trace[i]['edge'], 'START-shaped attempt was aborted')

    if not (out(trace[i - 1], 'sda_oen') == 1 and
            out(trace[i - 1], 'scl_oen') == 1):
        return (False, trace[i]['edge'],
                'START sequence did not first have sda_oen=1 and scl_oen=1 before SDA was pulled low')

    for k in range(i + 1, len(trace)):
        if aborted(trace[k]):
            return (None, trace[k]['edge'], 'START sequence was aborted before completion')
        if out(trace[k], 'cmd_ack') == 1:
            return (False, trace[k]['edge'],
                    'cmd_ack asserted before scl_oen was pulled low')

    scl_fall = None
    for j in range(i + 1, len(trace)):
        if (out(trace[j - 1], 'scl_oen') != 0 and
                out(trace[j], 'scl_oen') == 0):
            scl_fall = j
            break

    if scl_fall is None:
        return (False, trace[i]['edge'],
                'SDA was pulled low for START, but scl_oen never fell to 0 afterward')

    ack = None
    for k in range(scl_fall + 1, len(trace)):
        if aborted(trace[k]):
            return (None, trace[k]['edge'], 'START sequence was aborted before cmd_ack')
        if out(trace[k], 'cmd_ack') == 1:
            ack = k
            break

    if ack is None:
        return (False, trace[scl_fall]['edge'],
                'START completed its SCL-low step but cmd_ack never asserted')

    if trace[ack].get('held') != 1:
        return (False, trace[ack]['edge'],
                f"cmd_ack was high for {trace[ack].get('held')} edges, expected exactly one clock cycle")

    if ack + 1 < len(trace) and out(trace[ack + 1], 'cmd_ack') == 1:
        return (False, trace[ack + 1]['edge'],
                'cmd_ack remained high beyond the required one-clock pulse')

    return (True, trace[ack]['edge'],
            'START-shaped sequence released SDA and SCL, pulled SDA low while SCL was released, pulled SCL low, and asserted cmd_ack for exactly one clock cycle')

def decide(trace):
    def out(row, port):
        return row.get('outputs', {}).get(port)

    def active(row):
        ins = row.get('inputs', {})
        return ins.get('ena') == 1 and ins.get('nReset') == 1 and ins.get('rst') == 0

    activations = []
    for i, row in enumerate(trace):
        if not active(row) or out(row, 'busy') != 1:
            continue
        prev = trace[i - 1] if i else None
        if prev is None or not active(prev) or out(prev, 'busy') != 1:
            activations.append(i)

    if not activations:
        return (None, None, 'STOP execution signature never occurred: busy did not rise while enabled and out of reset')

    for start in activations:
        sda_index = None
        for i in range(start, len(trace)):
            if not active(trace[i]):
                break
            prev = trace[i - 1] if i else None
            if out(trace[i], 'sda_oen') == 0 and (prev is None or out(prev, 'sda_oen') != 0):
                sda_index = i
                break

        if sda_index is None:
            return (False, trace[start]['edge'], 'sda_oen never asserted low after the command sequence began')

        scl_index = None
        for i in range(sda_index + 1, len(trace)):
            if not active(trace[i]):
                break
            if out(trace[i], 'scl_oen') == 1 and out(trace[i - 1], 'scl_oen') != 1:
                scl_index = i
                break

        if scl_index is None:
            return (False, trace[sda_index]['edge'], 'scl_oen was not released high after sda_oen was asserted low')

    return (True, trace[activations[0]]['edge'], 'sda_oen was asserted low before scl_oen transitioned high')

def decide(trace):
    # `scl_oen` is the only routed declared output for this requirement.
    # Its changes reveal phase advances, but no declared trace port reveals
    # whether the internal `clk_en` was asserted for those advances.
    observed = [
        r for i, r in enumerate(trace)
        if i > 0
        and r['outputs'].get('scl_oen') != trace[i - 1]['outputs'].get('scl_oen')
    ]
    if observed:
        return (None, observed[0]['edge'],
                'scl_oen phase advance observed, but internal clk_en gating is not observable')
    return (None, None,
            'scl_oen did not reveal a phase advance, and internal clk_en gating is not observable')

def decide(trace):
    valid = lambda r: (
        r['inputs'].get('ena') == 1
        and r['inputs'].get('nReset') != 0
        and r['inputs'].get('rst') != 1
    )

    pulses = []
    i = 0
    while i < len(trace):
        row = trace[i]
        if row['outputs'].get('cmd_ack') != 1 or not valid(row):
            i += 1
            continue

        start = row
        duration = 0
        j = i
        while (j < len(trace)
               and trace[j]['outputs'].get('cmd_ack') == 1
               and valid(trace[j])):
            duration += trace[j].get('held', 1)
            j += 1

        if j == len(trace):
            return (None, start['edge'],
                    'cmd_ack pulse reaches the trace end; its exact duration is unknown')
        if duration != 1:
            return (False, start['edge'],
                    f'cmd_ack was high for {duration} clock edges, expected exactly one')
        pulses.append(start)
        i = j

    if not pulses:
        return (None, None,
                'no enabled, out-of-reset cmd_ack pulse was observed; command completion is not identifiable in this trace')

    return (True, pulses[-1]['edge'],
            f'{len(pulses)} enabled cmd_ack pulse(s) observed, each high for exactly one clock edge')

def decide(trace):
    # busy is the declared indirect observation route for this requirement.
    # The trace does not expose filter-sample boundaries, so a busy value
    # cannot be classified as the short-glitch or majority-filter case.
    busy_rows = [r for r in trace if 'busy' in r.get('outputs', {})]
    if not busy_rows:
        return (None, None, 'declared observation port busy is absent from this trace')
    return (None, None, 'busy is observable, but filter-sample intervals and internal sSCL/sSDA histories are not exposed')

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def _reset_asserted(row):
    inputs = row['inputs']
    return inputs.get('nReset') == 0 or inputs.get('rst') == 1


def _reset_outputs(row):
    outputs = row['outputs']
    return (
        outputs.get('scl_oen') == 1
        and outputs.get('sda_oen') == 1
        and outputs.get('cmd_ack') == 0
        and outputs.get('al') == 0
        and outputs.get('busy') == 0
    )


def decide(trace):
    windows = after(trace, _reset_asserted, until=WHILE_ACTIVE)
    return worst([
        throughout(w, _reset_outputs, after_activation=False)
        for w in windows
    ])

def decide(trace):
    sampled_cmd_ack = [row['outputs']['cmd_ack'] for row in trace]
    return (None, None, 'cmd_ack is sampled only at rising-edge states; the trace cannot reveal whether its updates occurred between rising edges')

def decide(trace):
    if not trace:
        return (None, None, 'module output assignments were not observed in this trace')

    for row in trace:
        outputs = row.get('outputs', {})
        for port in ('scl_o', 'sda_o'):
            if outputs.get(port) != 0:
                return (
                    False,
                    row.get('edge'),
                    f'{port} is not constant low; expected logic 0 at each observation'
                )

    return (
        True,
        None,
        'scl_o and sda_o remained constant logic 0 at every observation; '
        'active-low output-enable semantics are not independently falsifiable '
        'from the declared output trace'
    )

def decide(trace):
    # sda_oen is the declared observable, but no independent READ
    # activation is identifiable: cmd's symbolic encoding is unspecified.
    for row in trace:
        _ = row['outputs'].get('sda_oen')
    return (None, None, 'READ activation is not identifiable: cmd has no declared encoding table and no independent output signature was provided')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def any_cond(alts):
        def pred(row):
