def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def any_cond(alts):
        def pred(row):
            for cond in alts:
                if all(row['outputs'].get(p, row['inputs'].get(p)) == v
                       for p, v in cond.items()):
                    return True
            return False
        return pred

    start_falls = edges(trace, 'sda_i', 'fall')
    stop_rises = edges(trace, 'sda_i', 'rise')

    def start(row):
        return row['edge'] in start_falls and row['inputs'].get('scl_i') == 1

    def stop(row):
        return row['edge'] in stop_rises and row['inputs'].get('scl_i') == 1

    aborts = any_cond([{'nReset': 0}, {'rst': 1}])

    busy_windows = after(trace, start, until=stop, aborts=aborts)
    set_checks = [
        eventually(w, lambda r: r['outputs'].get('busy') == 1,
                   after_activation=True, strong=True)
        for w in busy_windows
    ]
    hold_checks = [
        throughout(w, lambda r: r['outputs'].get('busy') == 1,
                   after_activation=True)
        for w in busy_windows
    ]

    clear_windows = after(trace, stop, until=TO_END, aborts=aborts)
    clear_checks = [
        eventually(w, lambda r: r['outputs'].get('busy') == 0,
                   after_activation=True, strong=True)
        for w in clear_windows
    ]

    return worst(set_checks + hold_checks + clear_checks)
